scripts.路人对话.txt:
// 路人对话：指路

	If ($Event == 30) @Event30; 

	Say("农夫：最近咋老有问路的……", 0);
	Return;
	
@Event30:
	If ($Talkmap005luren == 0) @Talk0;
	If ($Talkmap005luren == 1) @Talk1;
  	If ($Talkmap005luren == 2) @Talk2;
  	
@Talk0:
	Say("独孤剑：这位大叔，请问去武夷山怎么走？", 1);
	Say("农夫：又是一位！呐，我告诉你：东北方向的路呢，是通往临安的；如果你要去武夷山，就往东南方向走。武夷山上有个九猴洞，九猴洞里有很多恶猴，记好了没有？", 0);
	Say("独孤剑：噢，多谢这位大叔了。", 2);
	Assign($Talkmap005luren, 1);
	Return;
  
@Talk1:	
	Say("农夫：前面不远就是武夷山。", 0);
	Assign($Talkmap005luren, 2);
	Return;
	
@Talk2:
	Say("农夫：最近怎么老有问路的？", 0);
	Return;

scripts.张琳心对话.txt:
// 与张琳心的同伴对话

	If ($Event == 210) @Event210;
	If ($Event == 240) @Event240;
	If ($Event == 250) @Event250;
	
	Return;
	
@Event210:
	Say("张琳心：独孤大哥，那封血书真的这么重要吗？", 24);
	Say("独孤剑：不错，血书关系重大，如果落在奸人手上，后果就不堪设想！", 1);
	Say("张琳心：奸人……", 24);
	Return;
	
@Event240:
	Say("独孤剑：我总觉得在血书背后隐藏着一个重大的阴谋，这个阴谋也许关系着武林的安危……", 1);
	Say("张琳心：已经有那么多的人为这封血书送了命，独孤大哥，你……", 21);
	Say("独孤剑：如果我不去揭穿这个阴谋，可能会死更多的人。", 1);
	Say("张琳心：……", 28);
	Say("独孤剑：张姑娘，你不必为我担心……", 2);
	Return;	
	
@Event250:
	Say("张琳心：独孤大哥，你随我回去，向我爹问清楚，这其中一定有误会……独孤大哥！", 28);
	Say("独孤剑：……好吧！", 1);
	Return;

