traps.trap04.txt:
//	路遇张风

	If ($Event == 240) @Event240;

	Return;
	
@Event240:
	StopMusic();
	PlayerGoto(7,23);
	SetPlayerDir(6);
	AddNpc("npc009_张风.ini", 12, 14, 5);
	MoveScreen(5, 70, 2);
	Sleep(500); 
	Say("张琳心：爹！？", 25);
	Sleep(200);
	SetNpcDir("张风", 1);
	SetNpcKind("张琳心", 1);
	NpcGotoEx("张琳心", 7, 21);
	SetNpcDir("张琳心", 5);
	Sleep(800);
	SetPlayerScn();
	Sleep(600);
	NpcGotoEx("张琳心", 11, 13);
	PlayerGoto(11, 16);
	SetNpcDir("张琳心", 7);
	SetPlayerDir(5);
	Say("张琳心：爹！你怎么会在这里……", 21);
	Say("张风：你就是独孤云之子，刘轻舟的徒弟？", 44);
	Say("独孤剑：你就是张风？你不配提起我爹的名字！", 5);
	
	SetNpcDir("张琳心", 0);
	
	Say("张琳心：爹，独孤大哥他……", 24);
	Say("张风：不错，老夫就是张风！", 44);
	Say("独孤剑：恶贼！你投敌卖国，卖友求荣，我今天就把国仇家恨和你一齐算清楚！", 5);
	Say("张琳心：独孤大哥，你！",25);
	Say("张风：骂得好！不错，你的父亲是我杀的，你找我报仇天经地义。", 44);
	Say("张风：不过，你说我投靠金国，不知有何凭据？",44);
	
	NpcGoto("张琳心", 11, 15);
	SetNpcDir("张琳心", 1);
	Say("张琳心：我爹决不会投靠金国的！", 27);
	Say("独孤剑：哼！今日你们父女俩就一块上，杀了我独孤剑，否则……", 5);
	Say("张琳心：你……",25);
	Say("张风：琳儿，你让开，凭他这点身手，就是十个也近不了老夫的身！", 44);
	SetNpcDir("张琳心",5);
	Say("张琳心：爹——不要！",24);
	Say("张风：让开！",44);
	
	NpcGoto("张琳心", 11, 14);
	SetNpcDir("张琳心", 7);
	
	Say("张风：哼，意气用事，有勇无谋，如何担当一派掌门！难道你忘了你师父和柳中原所托之事？今日你若死在此地，谁来揭露这个大阴谋！", 44);
	Say("独孤剑：连杀父之仇都报不了，还有何面目立足方寸之地！", 5);
	
	SetNpcDir("张琳心", 0);
	
	Say("张琳心：独孤大哥……你快走吧！", 26);
	Say("张风：蠢材，蠢材！世间之事岂有你想的那么简单！今日若不给你一点教训，恐怕你不知江湖的深浅。", 44);
	
	NpcGoto("张琳心", 11, 13);
	SetNpcDir("张琳心", 7);
	
	Say("张琳心：爹！", 26);
	SetNpcKind("独孤剑", 1);
	SetNpcKind("张琳心", 2); //临时切换主角
	
	PlaySound("战_男攻04");
	SetNpcMagicFile("张风","magic046_投石惊浪.ini");
	NpcAttack("张风", 11, 16);
	Sleep(1500);
	
	PlaySound("战_男死00.wav");
	SetNpcActionFile("独孤剑", 0, "npc001_body.asf");
	SetNpcActionFile("独孤剑", 1, "npc001_body.asf");
	NpcSpecialAction("独孤剑", "npc001_die.asf");
	Sleep(2000);
	
	NpcGoto("张琳心", 11, 15);
	SetNpcDir("张琳心", 1);
	Say("张琳心：独孤大哥！", 26);
	Say("张风：放心，我只是闭了他的心脉，让他暂时昏过去。", 44);
	Sleep(1000);
	Say("张风：唉！丫头，你到底是在帮这小子，还是在帮爹啊！", 44);
	
	SetNpcDir("张琳心", 5); 
	Say("张琳心：爹，女儿当然是……关心你了……", 22);
	Say("张风：关心我是不是打伤了他，是吗？", 44);
	Say("张琳心：……", 22);
	Say("张风：爹劝你还是不要跟着这小子了。对了，临安已有变故，你暂时不要回家了。", 44);
	Say("张琳心：爹……", 25);
	Say("张风：这封血书你还给他，记着，不要回临安找我！", 44);
	
	NpcGoto("张风", 16, 4);
	DelNpc("张风");
	SaveNpc();
	Sleep(500);
	
	FadeOut();
	SetNpcKind("张琳心", 1);
	SetNpcKind("独孤剑", 2); //恢复主角
	Say("过了良久，独孤剑苏醒过来。");
	SetNpcActionFile("独孤剑", 0, "npc001_st2.asf");
	SetNpcActionFile("独孤剑", 1, "npc001_sst2.asf");
	SetNpcPos("张琳心", 11, 15);
	SetNpcDir("张琳心", 1);
	SetPlayerPos(11, 16);
	SetPlayerDir(5);
	FadeIn();
	
	PlayMusic("长路.mp3");
	Say("独孤剑：你还留在这里干什么？……", 1);
	Say("张琳心：我记得你曾经说过，你不会因为父辈的仇怨而对我有成见。", 28);
	Say("独孤剑：我，我……", 6);
	Say("张琳心：我爹他一辈子杀了很多人，可是到头来终究逃不脱被人恨、被人追杀的结局。我不想，不想看到我关心的人都变成这样……独孤大哥！", 28);
	Say("独孤剑：……", 1);
	Say("张琳心：……", 28);	
	Say("独孤剑：对不起，我……", 1);
	Say("张琳心：其实我爹爹为官清廉，上任后做了不少利国利民的事，在家也是个好父亲。独孤大哥，我不相信我爹会是那种人，他一定有苦衷。", 28);
	Say("独孤剑：可是，师傅是不会骗我的……而且，你爹也亲口承认是他杀死了我爹。", 1);
	Say("张琳心：为什么会这样？为什么！", 28);
	Say("独孤剑：……", 1);
	Say("张琳心：这……这封血书，是爹叫我还给你的。", 28);
	Say("独孤剑：……", 1);
	AddGoods("Goods401_血书.ini");
	Say("张琳心：独孤大哥，你随我回去，回去向我爹问清楚。爹爹不会是这样的人，这里一定有误会……独孤大哥！", 28);
	Say("独孤剑：……好吧！", 1);
		
	SetNpcKind("张琳心", 3);
	Assign($Event, 250);
	SetMapTrap(1,"Trap01.txt");
	SetMapTrap(2,"Trap02.txt");
	SetMapTrap(3,"Trap03.txt");
	SetMapTrap(4,"");
	Memo("在去临安的路上，遇见张风，将血书交还他们，同时警告他们不要去临安。张风离开后，两人觉得事有蹊跷，决定前往临安");
	Return;
